/**
 * One run.
 */
public protocol AgentRunProtocol: AnyObject, Sendable {

    /**
     * Files the run created or changed in its working directory.
     */
    func artifacts() async throws  -> [AgentArtifact]

    /**
     * Events after `cursor` (0: from the start), at most `max`.
     */
    func events(cursor: UInt64, max: UInt32?) async throws  -> AgentEventPage

    func harness()  -> String

    /**
     * Cancels the turn in flight; the session stays open.
     */
    func interrupt() async throws  -> AgentRunInfo

    /**
     * Stops the run and deletes its directory (secrets included).
     */
    func remove() async throws

    /**
     * The last turn's outcome.
     */
    func result() async throws  -> AgentRunResult

    func runId()  -> String

    /**
     * A follow-up in the same session (queued while a turn runs).
     */
    func send(text: String, files: [AgentFile]?) async throws  -> AgentRunInfo

    func status() async throws  -> AgentRunInfo

    /**
     * Stops the run and verifies its process is gone.
     */
    func stop() async throws  -> AgentRunInfo

    /**
     * Waits until no turn is running (at most `timeout_ms`), then returns
     * the result.
     */
    func wait(timeoutMs: UInt64?) async throws  -> AgentRunResult

}
