// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceAudioSink {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceAudioSink] = [UniffiVTableCallbackInterfaceAudioSink(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeAudioSink.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface AudioSink: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeAudioSink.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface AudioSink: handle missing in uniffiClone")
            }
        },
        onAudio: { (
            uniffiHandle: UInt64,
            packet: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeAudioSink.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onAudio(
                     packet: try FfiConverterTypeAudioPacket_lift(packet)
                )
            }


            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )]
}

private func uniffiCallbackInitAudioSink() {
    uniffi_cua_sdk_fn_init_callback_vtable_audiosink(UniffiCallbackInterfaceAudioSink.vtable)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAudioSink: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<AudioSink>()

    typealias FfiType = UInt64
    typealias SwiftType = AudioSink

    public static func lift(_ handle: UInt64) throws -> AudioSink {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return AudioSinkImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: AudioSink) -> UInt64 {
         if let rustImpl = value as? AudioSinkImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AudioSink {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: AudioSink, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


