#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSpaces: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Spaces

    public static func lift(_ handle: UInt64) throws -> Spaces {
        return Spaces(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Spaces) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Spaces {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Spaces, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSpaces_lift(_ handle: UInt64) throws -> Spaces {
    return try FfiConverterTypeSpaces.lift(handle)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSpaces_lower(_ value: Spaces) -> UInt64 {
    return FfiConverterTypeSpaces.lower(value)
}






/**
 * Client for one cua-spacesd.
 */
public protocol SpacesdClientProtocol: AnyObject, Sendable {

    /**
     * Coding agents in this guest.
     */
    func agents() async throws  -> Agents

    /**
     * Attaches to a running process by pid or tag.
     */
    func attach(pid: UInt32?, tag: String?, replay: ReplayMode) async throws  -> SpacesdProcess

    /**
     * Calls any unary `cua.env.v1` RPC with a proto3-JSON request and
     * returns the proto3-JSON response. `method` is the full path
     * (`/cua.env.v1.WindowsService/ListWindows`) or `Service/Method`.
     * Covers windows, accessibility, driver tools, teleport, tunnels and
     * every other RPC without a typed method.
     */
    func callJson(method: String, requestJson: String) async throws  -> String

    /**
     * Calls a server-streaming `cua.env.v1` RPC and collects at most
     * `max_messages` responses (or until the stream ends or `timeout_ms`
     * elapses).
     */
    func callJsonStream(method: String, requestJson: String, maxMessages: UInt32, timeoutMs: UInt32) async throws  -> [String]

    /**
     * `GetCapabilities` (cached).
     */
    func capabilities() async throws  -> SpacesdCapabilities

    /**
     * Left click.
     */
    func click(x: Double, y: Double) async throws

    /**
     * Pointer position.
     */
    func cursorPosition() async throws  -> Point

    /**
     * Runs the image self-test (`SystemService.Diagnose`, the checks of
     * `cua-spacesd doctor`) and returns the report as JSON (schema version
     * 1, `libs/cua/proto/diagnose-report.schema.json`). `options_json` is a
     * proto3-JSON `DiagnoseOptions` (`"{}"` for the defaults: every check,
     * read-only). Falls back to `DiagnoseOnce` when the stream is cut.
     */
    func diagnose(optionsJson: String) async throws  -> String

    /**
     * Displays as proto3 JSON (`[Display]`).
     */
    func displays() async throws  -> String

    /**
     * Double click.
     */
    func doubleClick(x: Double, y: Double) async throws

    /**
     * Downloads `path` into memory.
     */
    func download(path: String) async throws  -> Data

    /**
     * Downloads `path` to a local file.
     */
    func downloadFile(path: String, localPath: String) async throws  -> TransferResult

    /**
     * Drags with the left button.
     */
    func drag(fromX: Double, fromY: Double, toX: Double, toY: Double) async throws

    /**
     * Endpoint URL.
     */
    func endpoint()  -> String

    /**
     * Clipboard text.
     */
    func getClipboard() async throws  -> String?

    /**
     * Whether the guest supports `feature`.
     */
    func hasFeature(feature: String) async throws  -> Bool

    /**
     * `Health` as proto3 JSON.
     */
    func health() async throws  -> String

    /**
     * Presses a chord (`["ctrl", "c"]`).
     */
    func hotkey(keys: [String]) async throws

    /**
     * Sends one plain-HTTP request to the spacesd port with this
     * client's endpoint and credentials (through the Fleet gateway when the
     * endpoint is a Fleet service). Used for streamable-HTTP MCP at `/mcp`,
     * for example by typed cua-driver clients. Not retried.
     */
    func http(request: SpacesdHttpRequest) async throws  -> SpacesdHttpResponse

    /**
     * Methods reachable through `call_json` / `call_json_stream`.
     */
    func jsonMethods()  -> [String]

    /**
     * Full `ComputerService.Keyboard` from proto3 JSON.
     */
    func keyboardJson(requestJson: String) async throws  -> String

    /**
     * `ListDir` (depth 1 = direct children).
     */
    func listDir(path: String, depth: UInt32) async throws  -> [FileEntry]

    /**
     * Guest processes as proto3 JSON (`[ProcessInfo]`).
     */
    func listProcesses(includeExited: Bool) async throws  -> String

    /**
     * `MakeDir` (with parents).
     */
    func makeDir(path: String) async throws  -> FileEntry

    /**
     * Moves the pointer.
     */
    func moveTo(x: Double, y: Double) async throws

    /**
     * Opens a media session and starts delivering encoded video frames and
     * control events to `frames`. Decoding stays in the host language.
     */
    func openMedia(options: MediaOpenOptions, frames: FrameSink) async throws  -> MediaSession

    /**
     * [`SpacesdClient::open_media`] that also delivers audio packets to
     * `audio` (set `options.audio` to negotiate audio tracks).
     *
     * Two methods instead of an optional sink: optional callback objects
     * do not lower in every binding generator.
     */
    func openMediaWithAudio(options: MediaOpenOptions, frames: FrameSink, audio: AudioSink) async throws  -> MediaSession

    /**
     * Full `ComputerService.Pointer` from proto3 JSON.
     */
    func pointerJson(requestJson: String) async throws  -> String

    /**
     * Presses one key (`enter`, `KEY_ESCAPE`, `a`, ...).
     */
    func press(key: String) async throws

    /**
     * `Remove`.
     */
    func remove(path: String, recursive: Bool) async throws

    /**
     * Right click.
     */
    func rightClick(x: Double, y: Double) async throws

    /**
     * Runs a command to completion.
     */
    func run(command: SpacesdCommand) async throws  -> ProcessOutput

    /**
     * Captures a display.
     */
    func screenshot(options: ScreenshotOptions?) async throws  -> Screenshot

    /**
     * Scrolls by line deltas.
     */
    func scroll(dx: Double, dy: Double) async throws

    /**
     * Sets clipboard text; returns the clipboard generation.
     */
    func setClipboard(text: String) async throws  -> UInt64

    /**
     * Runs `line` with `/bin/sh -c` to completion.
     */
    func sh(line: String, timeoutMs: UInt32?) async throws  -> ProcessOutput

    /**
     * Starts a command and returns its handle.
     */
    func spawn(command: SpacesdCommand) async throws  -> SpacesdProcess

    /**
     * `Stat`.
     */
