// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceTeleportApprover {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceTeleportApprover] = [UniffiVTableCallbackInterfaceTeleportApprover(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeTeleportApprover.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface TeleportApprover: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeTeleportApprover.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface TeleportApprover: handle missing in uniffiClone")
            }
        },
        approve: { (
            uniffiHandle: UInt64,
            manifest: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> TeleportDecision? in
                guard let uniffiObj = try? FfiConverterTypeTeleportApprover.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.approve(
                     manifest: try FfiConverterTypeTeleportManifest_lift(manifest)
                )
            }


            let writeReturn = { uniffiOutReturn.pointee = FfiConverterOptionTypeTeleportDecision.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )]
}

private func uniffiCallbackInitTeleportApprover() {
    uniffi_cua_sdk_fn_init_callback_vtable_teleportapprover(UniffiCallbackInterfaceTeleportApprover.vtable)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTeleportApprover: FfiConverter {
    fileprivate static let handleMap = UniffiHandleMap<TeleportApprover>()

    typealias FfiType = UInt64
    typealias SwiftType = TeleportApprover

    public static func lift(_ handle: UInt64) throws -> TeleportApprover {
        if ((handle & 1) == 0) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return TeleportApproverImpl(unsafeFromHandle: handle)
        } else {
            // Swift-generated handle, get the object from the handle map
            return try handleMap.remove(handle: handle)
        }
    }

    public static func lower(_ value: TeleportApprover) -> UInt64 {
         if let rustImpl = value as? TeleportApproverImpl {
             // Rust-implemented object.  Clone the handle and return it
            return rustImpl.uniffiCloneHandle()
         } else {
            // Swift object, generate a new vtable handle and return that.
            return handleMap.insert(obj: value)
         }
