/**
 * One normalized event.
 */
public struct AgentEvent: Equatable, Hashable {
    public var seq: UInt64
    public var tsMs: UInt64
    public var turn: UInt32
    /**
     * `message`, `thought`, `tool_call`, `tool_update`, `plan`, `usage`,
     * `permission`, `turn_started`, `turn_ended`, `install`, `error`,
     * `exited`, ... (see `harnesses()`).
     */
    public var kind: String
    public var text: String?
    public var toolId: String?
    public var toolTitle: String?
    public var toolKind: String?
    public var toolStatus: String?
    public var stopReason: String?
    /**
     * How a conversation view shows it: `message` (the agent's words),
     * `user` (the prompt as the agent got it), `activity` (a muted one-line
     * row: install, thinking, tools, plan, turn end, notice, error, exit)
     * or `hidden`. See [`AgentTranscript`].
     */
    public var category: String
    /**
     * One short line for an `activity` event.
     */
    public var summary: String?
    /**
     * One human-readable line, when the kind has one.
     */
    public var line: String?
    /**
     * The event as written (ACP payload included), JSON.
     */
    public var json: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(seq: UInt64, tsMs: UInt64, turn: UInt32,
        /**
         * `message`, `thought`, `tool_call`, `tool_update`, `plan`, `usage`,
         * `permission`, `turn_started`, `turn_ended`, `install`, `error`,
         * `exited`, ... (see `harnesses()`).
         */kind: String, text: String?, toolId: String?, toolTitle: String?, toolKind: String?, toolStatus: String?, stopReason: String?,
        /**
         * How a conversation view shows it: `message` (the agent's words),
         * `user` (the prompt as the agent got it), `activity` (a muted one-line
         * row: install, thinking, tools, plan, turn end, notice, error, exit)
         * or `hidden`. See [`AgentTranscript`].
         */category: String,
        /**
         * One short line for an `activity` event.
         */summary: String?,
        /**
         * One human-readable line, when the kind has one.
         */line: String?,
        /**
         * The event as written (ACP payload included), JSON.
         */json: String) {
        self.seq = seq
        self.tsMs = tsMs
        self.turn = turn
        self.kind = kind
        self.text = text
        self.toolId = toolId
        self.toolTitle = toolTitle
        self.toolKind = toolKind
        self.toolStatus = toolStatus
        self.stopReason = stopReason
        self.category = category
        self.summary = summary
        self.line = line
        self.json = json
    }




}

