/**
 * A presence event.
 */
public struct PresenceEvent: Equatable, Hashable {
    /**
     * `joined`, `left`, `cursor_moved`, `shape_changed`, `heartbeat` or
     * `keep_alive`.
     */
    public var kind: String
    /**
     * `joined`: who.
     */
    public var participant: PresenceParticipant?
    /**
     * `left` / `cursor_moved` / `shape_changed`: whose.
     */
    public var participantId: String?
    /**
     * `cursor_moved`: where.
     */
    public var cursor: PresenceCursor?
    /**
     * `shape_changed`: the new shape.
     */
    public var shape: String?
    /**
     * `shape_changed`: how it was determined.
     */
    public var shapeSource: String?
    /**
     * `left`: why (`left`, `disconnected`, `timeout`, `run_ended`, or
     * empty).
     */
    public var reason: String?
    /**
     * `heartbeat`: everyone present.
     */
    public var participantIds: [String]?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * `joined`, `left`, `cursor_moved`, `shape_changed`, `heartbeat` or
         * `keep_alive`.
         */kind: String,
        /**
         * `joined`: who.
         */participant: PresenceParticipant?,
        /**
         * `left` / `cursor_moved` / `shape_changed`: whose.
         */participantId: String?,
        /**
         * `cursor_moved`: where.
         */cursor: PresenceCursor?,
        /**
         * `shape_changed`: the new shape.
         */shape: String? = nil,
        /**
         * `shape_changed`: how it was determined.
         */shapeSource: String? = nil,
        /**
         * `left`: why (`left`, `disconnected`, `timeout`, `run_ended`, or
         * empty).
         */reason: String? = nil,
        /**
         * `heartbeat`: everyone present.
         */participantIds: [String]? = nil) {
        self.kind = kind
        self.participant = participant
        self.participantId = participantId
        self.cursor = cursor
        self.shape = shape
        self.shapeSource = shapeSource
        self.reason = reason
        self.participantIds = participantIds
    }




}

