// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What happened to one target.
 */

public enum AgentSetupChange: Equatable, Hashable {

    /**
     * Written where nothing was.
     */
    case created
    /**
     * Replaced or edited.
     */
    case updated
    /**
     * Already as wanted.
     */
    case unchanged
    /**
     * Removed (or the previous entry restored).
     */
    case removed
    /**
     * Deliberately left alone (see detail).
     */
    case skipped
    /**
     * Failed (see detail); the target was left untouched.
     */
    case failed





}

#if compiler(>=6)
extension AgentSetupChange: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAgentSetupChange: FfiConverterRustBuffer {
    typealias SwiftType = AgentSetupChange

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AgentSetupChange {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .created

        case 2: return .updated

        case 3: return .unchanged

        case 4: return .removed

        case 5: return .skipped

        case 6: return .failed

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AgentSetupChange, into buf: inout [UInt8]) {
        switch value {


        case .created:
            writeInt(&buf, Int32(1))


        case .updated:
            writeInt(&buf, Int32(2))


        case .unchanged:
            writeInt(&buf, Int32(3))


        case .removed:
            writeInt(&buf, Int32(4))


        case .skipped:
            writeInt(&buf, Int32(5))


        case .failed:
            writeInt(&buf, Int32(6))

        }
    }
}


